import pathlib, sys
banned = ['trpc.group/trpc-go', 'os/exec', 'net/http', 'net/']
bad = []
for p in sorted(pathlib.Path('agentloop').rglob('*.go')):
    text = p.read_text(encoding='utf-8')
    for needle in banned:
        if needle in text:
            bad.append(p.as_posix() + ' imports ' + needle)
print('agentloop stays provider-free: OK' if not bad else repr(bad))
sys.exit(1 if bad else 0)

